#!/usr/bin/env bash
# Generated by OrchestKit Claude Plugin
# Created: 2026-03-24

# Test parse-frontmatter.js — especially multiline scalar support
set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
PROJECT_ROOT="${CLAUDE_PROJECT_DIR:-$(cd "$SCRIPT_DIR/../.." && pwd)}"
PARSER="$PROJECT_ROOT/scripts/lib/parse-frontmatter.js"

RED='\033[0;31m'
GREEN='\033[0;32m'
NC='\033[0m'

PASS=0
FAIL=0

pass() { echo -e "  ${GREEN}✓${NC} $1"; PASS=$((PASS + 1)); }
fail() { echo -e "  ${RED}✗${NC} $1"; FAIL=$((FAIL + 1)); }

# Helper: parse frontmatter and extract a field
parse_field() {
  local content="$1"
  local field="$2"
  node -e "
    const { parseYamlFrontmatter } = require('$PARSER');
    const result = parseYamlFrontmatter(\`$content\`);
    const val = result.frontmatter['$field'];
    if (val === undefined) process.exit(1);
    console.log(typeof val === 'string' ? val : JSON.stringify(val));
  "
}

echo "============================================================================"
echo "  parse-frontmatter.js Tests"
echo "============================================================================"
echo ""

# Test 1: Simple key-value
echo "▶ Test 1: Simple key-value"
result=$(parse_field '---
name: my-skill
version: 1.0.0
---
body' "name")
[[ "$result" == "my-skill" ]] && pass "Simple string value" || fail "Expected 'my-skill', got '$result'"

# Test 2: Quoted string
echo "▶ Test 2: Quoted string"
result=$(parse_field '---
description: "A quoted description with spaces"
---
body' "description")
[[ "$result" == "A quoted description with spaces" ]] && pass "Quoted string" || fail "Expected unquoted, got '$result'"

# Test 3: Inline array
echo "▶ Test 3: Inline array"
result=$(parse_field '---
tags: [a, b, c]
---
body' "tags")
[[ "$result" == '["a","b","c"]' ]] && pass "Inline array" || fail "Expected array, got '$result'"

# Test 4: Boolean values
echo "▶ Test 4: Booleans"
result=$(parse_field '---
user-invocable: true
---
body' "user-invocable")
[[ "$result" == "true" ]] && pass "Boolean true" || fail "Expected true, got '$result'"

# Test 5: Multi-line array (- items)
echo "▶ Test 5: Multi-line array"
result=$(parse_field '---
tools:
  - Read
  - Write
  - Edit
---
body' "tools")
[[ "$result" == '["Read","Write","Edit"]' ]] && pass "Multi-line array" || fail "Expected array, got '$result'"

# Test 6: >- folded scalar (THE BUG WE FIXED)
echo "▶ Test 6: >- folded scalar"
result=$(parse_field '---
description: >-
  This is a long description
  that spans multiple lines
  and should be joined.
name: after
---
body' "description")
if [[ "$result" == *"This is a long description"* ]] && [[ "$result" == *"that spans multiple lines"* ]]; then
  pass ">- folded scalar joins lines"
else
  fail "Expected joined string, got '$result'"
fi

# Test 7: >- doesn't eat the next key
echo "▶ Test 7: >- stops at next key"
result=$(parse_field '---
description: >-
  Multi line desc.
name: my-skill
---
body' "name")
[[ "$result" == "my-skill" ]] && pass ">- stops at next key" || fail "Expected 'my-skill', got '$result'"

# Test 8: | literal scalar
echo "▶ Test 8: | literal scalar"
result=$(parse_field '---
description: |
  Literal block scalar
  preserves newlines.
name: test
---
body' "description")
[[ -n "$result" ]] && [[ "$result" == *"Literal block scalar"* ]] && pass "| literal scalar" || fail "Expected content, got '$result'"

# Test 9: nested mapping (CC 2.1.248 agent frontmatter `experimental.cacheTtl`)
echo "▶ Test 9: nested mapping"
result=$(parse_field '---
name: agent
experimental:
  # comment lines inside the block carry no data
  cacheTtl: 1h
tools:
  - Read
---
body' "experimental")
[[ "$result" == '{"cacheTtl":"1h"}' ]] && pass "Nested mapping parses as an object" || fail "Expected {\"cacheTtl\":\"1h\"}, got '$result'"

# Test 10: nested mapping does not eat the next key
echo "▶ Test 10: nested mapping stops at next key"
result=$(parse_field '---
experimental:
  cacheTtl: 1h
tools:
  - Read
  - Write
---
body' "tools")
[[ "$result" == '["Read","Write"]' ]] && pass "Array after nested mapping intact" || fail "Expected [\"Read\",\"Write\"], got '$result'"

# Test 9: > folded scalar (no dash)
echo "▶ Test 9: > folded scalar"
result=$(parse_field '---
description: >
  Folded without dash
  also works.
name: test
---
body' "description")
[[ "$result" == *"Folded without dash"* ]] && pass "> folded scalar" || fail "Expected content, got '$result'"

# Test 10: Description length check (not 2 chars)
echo "▶ Test 10: >- description length > 2"
result=$(parse_field '---
description: >-
  json-render component catalog patterns for AI-safe generative UI.
  Define Zod-typed catalogs that constrain what AI can generate.
name: json-render-catalog
---
body' "description")
len=${#result}
[[ "$len" -gt 50 ]] && pass "Description length $len chars (not 2)" || fail "Description only $len chars — parser still broken"

# Test 11: house keys under metadata lift to the top level (m1 spec shape)
echo "▶ Test 11: metadata house keys lift"
M1_DOC='---
name: m1-skill
metadata:
  category: workflow-automation
  version: "1.2.0"
  complexity: "low"
  tags: "git, commit, conventional-commits"
---
body'
result=$(parse_field "$M1_DOC" "tags")
[[ "$result" == '["git","commit","conventional-commits"]' ]] && pass "metadata tags lift to an array" || fail "Expected tags array, got '$result'"
result=$(parse_field "$M1_DOC" "version")
[[ "$result" == "1.2.0" ]] && pass "metadata version lifts" || fail "Expected 1.2.0, got '$result'"
result=$(parse_field '---
name: m1-skill
version: 9.9.9
metadata:
  version: "1.2.0"
---
body' "version")
[[ "$result" == "9.9.9" ]] && pass "top-level value wins over metadata" || fail "Expected 9.9.9, got '$result'"
result=$(parse_field "$M1_DOC" "category")
[[ "$result" == "workflow-automation" ]] && pass "metadata category lifts (m3)" || fail "Expected workflow-automation, got '$result'"
# parse_field exits 1 with no output when the key is absent at top level.
result=$(parse_field '---
name: m1-skill
metadata:
  owner: "someone"
---
body' "owner" || echo "absent")
[[ "$result" == "absent" ]] && pass "non-house metadata keys stay under metadata" || fail "owner leaked to top level: '$result'"

# Test 12: agent house keys under metadata lift (m3 shape)
echo "▶ Test 12: m3 agent metadata lift"
# The first prompt holds commas (as src/agents/frontend-ui-developer.md does),
# so examplePrompts must split on "|" and never on ",".
M3_DOC='---
name: m3-agent
model: sonnet
metadata:
  category: "frontend"
  critical_system_reminder: "Never skip a layer, even if it seems redundant."
  taskTypes: "build, design"
  keywords: "react, design system, ui"
  examplePrompts: "Build a data table component with sorting, filtering, and pagination | Create a multi-step form"
  required_mcp_servers: "21st-dev-magic, context7"
---
body'
result=$(parse_field "$M3_DOC" "examplePrompts")
[[ "$result" == '["Build a data table component with sorting, filtering, and pagination","Create a multi-step form"]' ]] \
  && pass "comma-bearing examplePrompt round-trips as one item" || fail "examplePrompts split wrong: '$result'"
result=$(parse_field "$M3_DOC" "taskTypes")
[[ "$result" == '["build","design"]' ]] && pass "metadata taskTypes lift to an array" || fail "Expected taskTypes array, got '$result'"
result=$(parse_field "$M3_DOC" "keywords")
[[ "$result" == '["react","design system","ui"]' ]] && pass "metadata keywords lift to an array" || fail "Expected keywords array, got '$result'"
result=$(parse_field "$M3_DOC" "required_mcp_servers")
[[ "$result" == '["21st-dev-magic","context7"]' ]] && pass "metadata required_mcp_servers lift to an array" || fail "Expected servers array, got '$result'"
result=$(parse_field "$M3_DOC" "critical_system_reminder")
[[ "$result" == "Never skip a layer, even if it seems redundant." ]] && pass "metadata critical_system_reminder lifts as a string" || fail "Got '$result'"
result=$(parse_field "$M3_DOC" "category")
[[ "$result" == "frontend" ]] && pass "metadata category lifts as a string" || fail "Expected frontend, got '$result'"
# The CLI entry the shell tests use prints the same lifted value.
M3_FILE=$(mktemp "${TMPDIR:-/tmp}/m3-agent.XXXXXX")
printf '%s\n' "$M3_DOC" > "$M3_FILE"
result=$(node "$PARSER" "$M3_FILE" category)
rm -f "$M3_FILE"
[[ "$result" == "frontend" ]] && pass "parser CLI prints the lifted category" || fail "CLI printed '$result'"

echo ""
echo "============================================================================"
echo "  Results: $PASS passed, $FAIL failed"
echo "============================================================================"

[[ "$FAIL" -eq 0 ]] || exit 1
